-- Modify "inventory_users" table
ALTER TABLE "inventory_users" ADD COLUMN IF NOT EXISTS "name" character varying NULL, ADD COLUMN IF NOT EXISTS "pin_hash" character varying NULL, ADD COLUMN IF NOT EXISTS "pin_fast_hash" character varying NULL, ADD COLUMN IF NOT EXISTS "pin_failed_attempts" bigint NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS "pin_locked_until" timestamptz NULL;
-- Modify "items" table
ALTER TABLE "items" ADD COLUMN IF NOT EXISTS "gtin" character varying NULL, ADD COLUMN IF NOT EXISTS "mpn" character varying NULL, ADD COLUMN IF NOT EXISTS "condition" character varying NOT NULL DEFAULT 'NEW', ADD COLUMN IF NOT EXISTS "slug" character varying NULL, ADD COLUMN IF NOT EXISTS "short_description" text NULL, ADD COLUMN IF NOT EXISTS "meta_title" character varying NULL, ADD COLUMN IF NOT EXISTS "meta_description" text NULL, ADD COLUMN IF NOT EXISTS "country_of_origin" character varying NULL, ADD COLUMN IF NOT EXISTS "hs_code" character varying NULL, ADD COLUMN IF NOT EXISTS "is_returnable" boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS "return_window_days" bigint NULL, ADD COLUMN IF NOT EXISTS "allow_backorder" boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS "is_discontinued" boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS "non_billable" boolean NOT NULL DEFAULT false;
-- Modify "suppliers" table
ALTER TABLE "suppliers" ADD COLUMN IF NOT EXISTS "address_line1" character varying NULL, ADD COLUMN IF NOT EXISTS "address_line2" character varying NULL, ADD COLUMN IF NOT EXISTS "city" character varying NULL, ADD COLUMN IF NOT EXISTS "address_state" character varying NULL, ADD COLUMN IF NOT EXISTS "address_postal_code" character varying NULL, ADD COLUMN IF NOT EXISTS "country" character varying NULL, ADD COLUMN IF NOT EXISTS "industry" character varying NULL, ADD COLUMN IF NOT EXISTS "website" character varying NULL, ADD COLUMN IF NOT EXISTS "notes" text NULL, ADD COLUMN IF NOT EXISTS "logo_url" character varying NULL, ADD COLUMN IF NOT EXISTS "bank_account_name" character varying NULL, ADD COLUMN IF NOT EXISTS "swift_bic" character varying NULL, ADD COLUMN IF NOT EXISTS "currency" character varying NULL, ADD COLUMN IF NOT EXISTS "vat_number" character varying NULL;
-- Backfill: ugali is a free accompaniment - never billed at the till (stock still deducts).
UPDATE "items" SET "non_billable" = true WHERE lower("name") LIKE '%ugali%';
